import subprocess, re

# The key offsets from libcoreclr in the crashing thread/exception backtrace
offsets = [0x3e1700, 0x2615fc, 0x16c31c, 0x16c620, 0x18b678, 0x49cc]

for off in offsets:
    result = subprocess.run(
        ['llvm-dwarfdump-18', '--lookup=0x{:x}'.format(off), 'libcoreclr.dSYM/Contents/Resources/DWARF/libcoreclr'],
        capture_output=True, text=True
    )
    output = result.stdout.strip()
    if output:
        # Extract function name and file info
        lines = output.split('\n')
        func = ''
        file_info = ''
        for line in lines:
            if 'DW_AT_name' in line and not func:
                m = re.search(r'DW_AT_name\s*\(\"(.+?)\"\)', line)
                if m:
                    func = m.group(1)
            if 'DW_AT_linkage_name' in line:
                m = re.search(r'DW_AT_linkage_name\s*\(\"(.+?)\"\)', line)
                if m:
                    func = m.group(1)
            if 'Line:' in line:
                file_info = line.strip()
        print(f'0x{off:x}: {func}  {file_info}')
    else:
        print(f'0x{off:x}: (no match)')
" 2>&1

