    result = subprocess.run(
        ['llvm-dwarfdump-18', '--lookup=0x{:x}'.format(off), '-p', 'libcoreclr.dSYM/Contents/Resources/DWARF/libcoreclr'],
        capture_output=True, text=True
    )
    output = result.stdout.strip()
    lines = output.split('\n')
    # Find the most relevant info
    func_names = []
    file_line = ''
    for line in lines:
        if 'DW_AT_linkage_name' in line:
            m = re.search(r'\(\"(.+?)\"\)', line)
            if m:
                func_names.append(m.group(1))
        elif 'DW_AT_name' in line and 'DW_TAG_subprogram' in ''.join(lines[max(0,lines.index(line)-3):lines.index(line)]):
            m = re.search(r'\(\"(.+?)\"\)', line)
            if m:
                func_names.append(m.group(1))
        if 'Line:' in line and 'File:' in line:
            file_line = line.strip()
    print(f'0x{off:x}:')
    if func_names:
        print(f'  Function: {func_names[-1]}')
    if file_line:
        print(f'  {file_line}')
    print()
