# Let's check what section it falls in by looking at nearby compile units
import subprocess
result = subprocess.run(['llvm-dwarfdump-18', '--debug-aranges', 'libcoreclr.dSYM/Contents/Resources/DWARF/libcoreclr'], capture_output=True, text=True)
# Search for ranges containing 0x3e1700
target = 0x3e1700
for line in result.stdout.split('\n'):
    if '0x' in line and 'length' in line.lower():
        parts = line.strip().split()
        # format: [0xaddr, 0xaddr)
        try:
            if '[' in line:
                start_str = line.split('[')[1].split(',')[0]
                end_str = line.split(',')[1].split(')')[0].strip()
                start = int(start_str, 16)
                end = int(end_str, 16)
                if start <= target < end:
                    print(f'Found: {line}')
        except:
            pass
